import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const statusLabel: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  exceeded: 'Превышена',
};

const statusTone: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  warning: 'warning',
  exceeded: 'danger',
};

const projects: Project[] = [
  { id: 'p1', name: 'Контекст-лаборатория', quota: 42, status: 'active' },
  { id: 'p2', name: 'Модерация контента', quota: 78, status: 'warning' },
  { id: 'p3', name: 'Ассистент поддержки', quota: 95, status: 'exceeded' },
  { id: 'p4', name: 'Поиск по документам', quota: 30, status: 'active' },
  { id: 'p5', name: 'Аналитика диалогов', quota: 88, status: 'warning' },
  { id: 'p6', name: 'Генерация отчётов', quota: 12, status: 'active' },
  { id: 'p7', name: 'Голосовой ассистент', quota: 101, status: 'exceeded' },
  { id: 'p8', name: 'Перевод документов', quota: 55, status: 'active' },
  { id: 'p9', name: 'Классификация тикетов', quota: 67, status: 'warning' },
  { id: 'p10', name: 'Суммаризация встреч', quota: 20, status: 'active' },
  { id: 'p11', name: 'Проверка кода', quota: 99, status: 'exceeded' },
  { id: 'p12', name: 'Рекомендательный движок', quota: 44, status: 'active' },
];

const statusFilters: ProjectStatus[] = ['active', 'warning', 'exceeded'];
const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(statusFilters);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusFilters);
    setPage(1);
  };

  const filtered = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {statusFilters.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onRemove={() => toggleStatus(status)}
            onClick={() => {
              if (!activeStatuses.includes(status)) {
                toggleStatus(status);
              }
            }}
          >
            {statusLabel[status]}
          </JxChip>
        ))}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным фильтрам проектов нет."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px 16px',
                  borderRadius: 'var(--jx-r-lg)',
                  border: '1px solid var(--jx-border)',
                  background: 'var(--jx-surface)',
                }}
              >
                <span style={{ color: 'var(--jx-text)' }}>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                  <JxProgressCircle value={Math.min(project.quota, 100)} showValue />
                  <JxBadge tone={statusTone[project.status]} dot>
                    {statusLabel[project.status]}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

